// Cross-implementation parity for the Flat Ring glyph (geometry 33/34, desktop
// 721b827) — a torus whose cross-section is a rectangle.
//
// The fixture is generated by tools/dump_ring_geometry.py, which runs the REAL
// desktop `_draw_ring` with the GL entry points swapped for recorders, so what
// is diffed is the exact vertex stream that app would have drawn.
//
// Two contracts, and they are the two reasons the shape exists rather than
// being a squashed torus:
//
//   * **It is the torus's own extents, restated as a box.** `ringDims` and
//     `torusRadii` agree, so Torus ↔ Flat Ring is a change of LOOK only:
//     identical silhouette, identical bounding extents, and a Torus-topology
//     parent places its children identically whichever the parent wears.
//     Anything that broke that would silently relocate children in every scene
//     that swapped the geometry — including the Armillary World, which is built
//     out of rings carrying exhibits.
//
//   * **No face is mirrored.** Each of the four faces carries a full 0–1 UV
//     span of its own so a strip of degree markings lands undistorted on it,
//     and each face's u runs forwards from that face's natural viewing side.
//     A ring's whole purpose is holding a legible texture, so a mirrored face
//     is not a cosmetic difference — it is a zodiac ring reading backwards.
//
// The web emits its vertices in the desktop's own per-face, per-station order,
// so the flat arrays diff element for element.

import { describe, expect, it } from 'vitest'
import { ringDims } from './glyphGeometry'
import { zRingGeometry, zRingWireGeometry } from './uvGeometry'
import { GEOMETRY_MAX, Geometry } from '../gv/types'
import fixtureRaw from './fixtures/ring_geometry.json?raw'

interface Vertex {
  pos: number[]
  uv: number[] | null
  normal: number[] | null
}

const fixture = JSON.parse(fixtureRaw) as {
  rings: number
  rungs: number
  defaults: { rings: number; rungs: number; ratio: number }
  ratioShapedGeometries: number[]
  ringIds: { solid: number; wire: number }
  dims: Array<{ ratio: number; ring_dims: number[]; torus_radii: number[] }>
  solid: Array<{ ratio: number; strips: Vertex[][] }>
  wire: Array<{ ratio: number; loops: number[][][] }>
}

/** Doubles on both sides, from the same closed-form expression — but the web
 *  stores its attributes as Float32Array, which is the whole of the slack. */
const TOL = 1e-6

describe('flat ring parity with desktop GlyphViz', () => {
  it('has cases to compare', () => {
    expect(fixture.solid.length).toBeGreaterThan(4)
    expect(fixture.wire.length).toBeGreaterThan(1)
  })

  it('agrees on the ids', () => {
    expect(fixture.ringIds.solid).toBe(Geometry.Ring)
    expect(fixture.ringIds.wire).toBe(Geometry.RingWire)
    // Appended, never renumbered: 0–22 are ANTz's own enum and 23–32 the
    // earlier GlyphViz extensions, all of them written into saved files.
    expect(Geometry.RingWire).toBe(GEOMETRY_MAX)
  })

  // ring_dims IS torus_radii restated — the equivalence a swap depends on.
  for (const entry of fixture.dims) {
    it(`ringDims(${entry.ratio}) matches the desktop`, () => {
      const [outer, inner, halfHeight] = ringDims(entry.ratio)
      expect(outer).toBeCloseTo(entry.ring_dims[0], 12)
      expect(inner).toBeCloseTo(entry.ring_dims[1], 12)
      expect(halfHeight).toBeCloseTo(entry.ring_dims[2], 12)
      // …and the torus it is restating: the tube spans major ± minor radially
      // and ±minor in z.
      const [major, minor] = entry.torus_radii
      expect(outer).toBeCloseTo(major + minor, 12)
      expect(inner).toBeCloseTo(Math.max(0, major - minor), 12)
      expect(halfHeight).toBeCloseTo(minor, 12)
    })
  }

  for (const entry of fixture.solid) {
    it(`the solid ring at ratio ${entry.ratio} emits the desktop's vertices`, () => {
      const geometry = zRingGeometry(...ringDims(entry.ratio), { rings: fixture.rings })
      const position = geometry.getAttribute('position')
      const normal = geometry.getAttribute('normal')
      const uv = geometry.getAttribute('uv')

      const expected = entry.strips.flat()
      expect(position.count).toBe(expected.length)

      for (let i = 0; i < expected.length; i++) {
        const want = expected[i]
        const where = `vertex ${i} of ratio ${entry.ratio}`
        expect([position.getX(i), position.getY(i), position.getZ(i)].map(round), where).toEqual(
          want.pos.map(round),
        )
        expect([normal.getX(i), normal.getY(i), normal.getZ(i)].map(round), where).toEqual(
          want.normal!.map(round),
        )
        expect([uv.getX(i), uv.getY(i)].map(round), where).toEqual(want.uv!.map(round))
      }
    })
  }

  for (const entry of fixture.wire) {
    it(`the wire ring at ratio ${entry.ratio} traces the desktop's loops`, () => {
      const geometry = zRingWireGeometry(...ringDims(entry.ratio), {
        rings: fixture.rings,
        rungs: fixture.rungs,
      })
      const position = geometry.getAttribute('position')

      // The desktop draws GL_LINE_LOOPs; three has no such primitive, so each
      // loop arrives here as its own closing run of segment pairs.
      const segments = entry.loops.reduce((total, loop) => total + 2 * loop.length, 0)
      expect(position.count).toBe(segments)

      let at = 0
      for (const loop of entry.loops) {
        for (let k = 0; k < loop.length; k++) {
          const from = [position.getX(at), position.getY(at), position.getZ(at)]
          const to = [position.getX(at + 1), position.getY(at + 1), position.getZ(at + 1)]
          expect(from.map(round)).toEqual(loop[k].map(round))
          expect(to.map(round)).toEqual(loop[(k + 1) % loop.length].map(round))
          at += 2
        }
      }
    })
  }

  it('draws at the desktop builder’s own tessellation by default', () => {
    // Not a formality: the shape is periodic, so a builder that agrees at the
    // fixture's 8 stations agrees at any count — which is exactly why the
    // DEFAULT has to be pinned separately, or the two apps could silently draw
    // a 48-sided band and a 12-sided one.
    const [outer, inner, halfHeight] = ringDims(fixture.defaults.ratio)
    const solid = zRingGeometry(outer, inner, halfHeight)
    expect(solid.getAttribute('position').count).toBe(4 * 2 * (fixture.defaults.rings + 1))

    const wire = zRingWireGeometry(outer, inner, halfHeight)
    expect(wire.getAttribute('position').count).toBe(
      2 * (4 * fixture.defaults.rings + 4 * fixture.defaults.rungs),
    )
  })
})

/** Float32 round-trip slack, applied to both sides before comparing. */
function round(value: number): number {
  const snapped = Math.round(value / TOL) * TOL
  return snapped === 0 ? 0 : snapped // fold −0, which the desktop emits for −sin 0
}
